-- 2026-11-19 KICE mathematics, 2027 academic year. Exam-day sources.
-- Existing references, manual difficulty decisions and user solutions are preserved.
begin;
set local lock_timeout = '10s';
alter table public.exam_sessions drop constraint exam_session_extended_rules;
alter table public.exam_sessions add constraint exam_session_extended_rules check (
 calendar_year between 2022 and 2026 and grade in ('고1','고2','고3') and (
  (provider='kice' and grade='고3' and academic_year=calendar_year+1
    and ((kind='mock' and month in (6,9)) or (kind='csat' and month=11))
    and (board_url like 'https://www.suneung.re.kr/boardCnts/view.do?%' or
         (calendar_year=2026 and kind='csat' and board_url='https://cdn2.kice.re.kr/27dae-suneung/index.html')))
  or (provider='education' and kind='education' and academic_year=calendar_year and month between 1 and 12
    and board_url like 'https://www.ebsi.co.kr/ebs/xip/xipa/retrieveSCVMainInfo.ebs?irecord=%')));

CREATE OR REPLACE FUNCTION private.valid_solution_drawing(d jsonb, p_problem_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s jsonb; p jsonb; v jsonb; total integer:=0; h numeric;
begin
 if d is null then return true; end if;
 if jsonb_typeof(d) is distinct from 'object' or not(d ?& array['version','problem_id','width','height','problem_height','source','strokes']) then return false; end if;
 if exists(select 1 from jsonb_object_keys(d) k where k not in ('version','problem_id','width','height','problem_height','source','strokes')) then return false; end if;
 if octet_length(d::text)>350000 or jsonb_typeof(d->'version') is distinct from 'number' or jsonb_typeof(d->'problem_id') is distinct from 'string' or d->>'version'<>'1' or d->>'problem_id'<>p_problem_id::text then return false; end if;
 if jsonb_typeof(d->'width') is distinct from 'number' or jsonb_typeof(d->'height') is distinct from 'number' or jsonb_typeof(d->'problem_height') is distinct from 'number' then return false; end if;
 h:=(d->>'height')::numeric;
 if (d->>'width')::numeric<>1000 or h<600 or h>6000 or trunc(h)<>h or (d->>'problem_height')::numeric<1 or (d->>'problem_height')::numeric>h or trunc((d->>'problem_height')::numeric)<>(d->>'problem_height')::numeric then return false; end if;
 if jsonb_typeof(d->'source') is distinct from 'object' or coalesce(d->'source'->>'kind','') not in ('exam','image') then return false; end if;
 v:=d->'source';
 if v->>'kind'='exam' then
  if not(v ?& array['official_url','pdf_page','crop']) or (coalesce(v->>'official_url','') !~ '^https://www[.]suneung[.]re[.]kr/boardCnts/fileDown[.]do[?]fileSeq=[a-f0-9]{32}$' and v->>'official_url' not in ('https://wdown.ebsi.co.kr/W61001/01exam/20261119/go3/live_main_paper_1_math_K63RYJL3.pdf', 'https://wdown.ebsi.co.kr/W61001/01exam/20261119/go3/live_main_paper_2_math_F51864J3.pdf')) or coalesce(v->>'pdf_page','') !~ '^([1-9]|[1-3][0-9]|40)$' then return false; end if;
  if jsonb_typeof(v->'crop') is distinct from 'array' then return false; end if;
  if jsonb_array_length(v->'crop')<>4 then return false; end if;
  for p in select value from jsonb_array_elements(v->'crop') loop if jsonb_typeof(p) is distinct from 'number' or p::numeric<0 or p::numeric>1 then return false; end if; end loop;
  if (v->'crop'->>0)::numeric >= (v->'crop'->>2)::numeric or (v->'crop'->>1)::numeric >= (v->'crop'->>3)::numeric then return false; end if;
  if exists(select 1 from jsonb_object_keys(v) k where k not in ('kind','official_url','pdf_page','crop','image_key','image_path')) then return false; end if;
  if v ? 'image_key' or v ? 'image_path' then
   if jsonb_typeof(v->'image_key') is distinct from 'string' or char_length(v->>'image_key') not between 1 and 160 or jsonb_typeof(v->'image_path') is distinct from 'string' or (v->>'image_path') !~ '^/exam-images/q-[a-f0-9]{24}[.]webp$' then return false; end if;
  end if;
 elsif exists(select 1 from jsonb_object_keys(v) k where k<>'kind') then return false;
 end if;
 if jsonb_typeof(d->'strokes') is distinct from 'array' then return false; end if;
 if jsonb_array_length(d->'strokes')<1 or jsonb_array_length(d->'strokes')>500 then return false; end if;
 for s in select value from jsonb_array_elements(d->'strokes') loop
  if jsonb_typeof(s) is distinct from 'object' or not(s ?& array['color','size','points']) then return false; end if;
  if exists(select 1 from jsonb_object_keys(s) k where k not in ('color','size','points')) then return false; end if;
  if coalesce(s->>'color','') not in ('#151713','#2456d6','#d63232','#16844a') or jsonb_typeof(s->'size') is distinct from 'number' then return false; end if;
  if (s->>'size')::numeric<1 or (s->>'size')::numeric>12 or jsonb_typeof(s->'points') is distinct from 'array' then return false; end if;
  if jsonb_array_length(s->'points')<1 then return false; end if;
  total:=total+jsonb_array_length(s->'points');if total>15000 then return false; end if;
  for p in select value from jsonb_array_elements(s->'points') loop
   if jsonb_typeof(p) is distinct from 'array' then return false; end if;
   if jsonb_array_length(p)<>2 or jsonb_typeof(p->0) is distinct from 'number' or jsonb_typeof(p->1) is distinct from 'number' then return false; end if;
   if (p->>0)::numeric<0 or (p->>0)::numeric>1000 or (p->>1)::numeric<0 or (p->>1)::numeric>h then return false; end if;
  end loop;
 end loop;
 return true;
exception when others then return false;
end $function$
;

