insert into public.exam_questions(id,session_id,variant,section,question_no,official_url,pdf_start_page,pdf_page,crop,unit_id,classification)
select id,'ecc7eb47-2da1-48a8-a547-f58dcb1b6807',variant,section,number,details->>'official_url',1,(details->>'pdf_page')::int,details->'crop',unit_id,details->'classification'
from csat_2027_questions on conflict(id) do nothing;

alter table public.problems disable trigger problems_rate;
alter table public.problems disable trigger problems_reward;
insert into public.problems(id,owner_id,exam_question_id,title,question,grade,subject,unit,unit_id,curriculum_id,source,source_details,public,rights_confirmed)
select id,null,id,title,'2027학년도 대학수학능력시험 수학 영역','고3',subject,unit,unit_id,'2015','수능',details,true,true
from csat_2027_questions on conflict(id) do nothing;
alter table public.problems enable trigger problems_rate;
alter table public.problems enable trigger problems_reward;

insert into public.problem_difficulties(problem_id,level,classification_method,correct_rate,rate_basis,source_url,source_exam_seq,rate_collected_at,rule_version)
select id,level,'correct_rate',rate,basis,rate_url,364,collected_at,'megastudy-20-50-80-v1' from csat_2027_questions
on conflict(problem_id) do nothing;

do $$begin
 if (select count(*) from csat_2027_questions r
  join public.exam_questions q on q.id=r.id and q.session_id='ecc7eb47-2da1-48a8-a547-f58dcb1b6807' and q.variant=r.variant and q.section=r.section
   and q.question_no=r.number and q.crop=r.details->'crop' and q.official_url=r.details->>'official_url'
  join public.problems p on p.exam_question_id=q.id and p.public and p.source='수능' and p.source_details->>'asset_path'=r.details->>'asset_path'
  join public.problem_difficulties d on d.problem_id=p.id and
   (d.classification_method='manual' or (d.correct_rate=r.rate and d.level=r.level))) <> 92
 then raise exception 'Incomplete or mismatched CSAT 2027 import'; end if;
end$$;
commit;
